// Uses only synthetic, complete matches generated by the App's three-mode regression test.
import {readFileSync,writeFileSync,mkdirSync} from 'node:fs';
import {randomBytes,randomUUID} from 'node:crypto';
import {createRequire} from 'node:module';
import {gzipSync,deflateSync} from 'node:zlib';
import assert from 'node:assert/strict';
const {webkit}=createRequire(import.meta.url)('/Users/JasonChan/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright');
const origin='https://baseballmaster.cc',base=origin+'/api/v3',out='output/validation/3.0/release-completion/production';mkdirSync(out,{recursive:true});
const folder='output/validation/3.0/release-completion/full-match-sources';
const fixtures=JSON.parse(readFileSync(folder+'/manifest.json')).flatMap(m=>m.attachments).map(a=>JSON.parse(readFileSync(folder+'/'+a.exportedFileName)));
const secret=()=>randomBytes(32).toString('base64url'),admin=secret(),member=secret(),stranger=secret(),measurements=[];
let team,browser,completed=false;
const request=async(key,method,path,body,expected=200)=>{
 const bytes=body?Buffer.from(JSON.stringify({operationID:randomUUID(),...body})):null;
 const started=performance.now(),r=await fetch(base+path,{method,headers:{'Content-Type':'application/json','X-BM-Protocol':'1',...(key?{Authorization:'Bearer '+key}:{}),...(bytes?{'Content-Encoding':'deflate'}:{})},body:bytes?deflateSync(bytes):undefined});
 const data=await r.json();assert.equal(r.status,expected,`${method} ${path}: ${r.status} ${data.error?.code??''}`);
 measurements.push({method,kind:path.includes('/games')?'match':path.split('/')[1],ms:performance.now()-started,requestBytes:bytes?.length??0,compressedBytes:bytes?deflateSync(bytes).length:0});return data;
};
const summary={startedAt:new Date().toISOString(),origin,synthetic:true,modes:fixtures.map(f=>({mode:f.payload.rules.mode,events:f.payload.state.scoringEvents.length,requestBytes:Buffer.byteLength(JSON.stringify(f)),gzipBytes:gzipSync(JSON.stringify(f)).length})),checks:[]};
try {
 for(const key of [admin,member,stranger])await request(key,'POST','/devices',{label:'发布验证 iPhone'});
 team=(await request(admin,'POST','/teams',{name:'发布验证临时球队',nickname:'验证记录员'})).teamID;
 const invite=secret();await request(admin,'POST',`/teams/${team}/invitations`,{role:'member',token:invite});await request(member,'POST','/invitations/redeem',{token:invite,nickname:'验证成员'});
 const games=[];
 for(let i=0;i<20;i++){
  const value=structuredClone(fixtures[i%fixtures.length]),id=randomUUID();value.payload.id=id;value.projection.gameID=id;
  const preserve=new Set([value.payload.state.homeTeam.id,value.payload.state.awayTeam.id,...value.payload.state.homeTeam.players.map(p=>p.id),...value.payload.state.awayTeam.players.map(p=>p.id),id].map(s=>s.toLowerCase()));
  const ids=new Map();const text=JSON.stringify(value).replace(/[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}/gi,old=>{if(preserve.has(old.toLowerCase()))return old;const key=old.toLowerCase();if(!ids.has(key))ids.set(key,randomUUID());return ids.get(key);});
  const body=JSON.parse(text),g=await request(admin,'POST',`/teams/${team}/games`,body);games.push(g);
  if(i<3){const read=await request(member,'GET',`/teams/${team}/games/${g.id}`);assert.deepEqual(read.payload,body.payload);assert.deepEqual(read.projection.snapshot.home.innings,body.projection.home.innings);}
 }
 summary.checks.push('20 complete matches saved; first three mode payloads and projections match the App');
 const game=games[0],path=`/teams/${team}/games/${game.id}`;
 await request(stranger,'GET',path,undefined,404);await request(member,'GET',`/teams/${team}/archive`,undefined,403);
 await request(member,'PUT',path,{...fixtures[0],baseRevision:1,writerEpoch:1},409);
 summary.checks.push('Cross-team reads, member writes and member archive exports denied');
 const manifest=await request(admin,'GET',`/teams/${team}/archive`);assert.equal(manifest.games.length,20);
 await request(admin,'GET',`/teams/${team}/archive/${game.id}?snapshot=${manifest.snapshot}`);
 await request(admin,'POST',`/teams/${team}/archive/finish`,{snapshot:manifest.snapshot});
 await request(admin,'POST',path+'/access',{mode:'public',baseAccessVersion:1});
 const latencies=[];await Promise.all(Array.from({length:30},async()=>{const start=performance.now();const r=await fetch(base+'/watch/'+game.viewCode,{headers:{'X-BM-Protocol':'1'}});assert.equal(r.status,200);await r.arrayBuffer();latencies.push(performance.now()-start);}));
 summary.concurrentReads={viewers:30,p50Ms:latencies.sort((a,b)=>a-b)[14],p95Ms:latencies[28],maximumMs:latencies[29]};
 browser=await webkit.launch();const context=await browser.newContext({viewport:{width:402,height:874},colorScheme:'dark'}),page=await context.newPage(),errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(origin+'/watch/#'+game.viewCode);await page.locator('#match').waitFor({state:'visible'});assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
 await page.screenshot({path:out+'/public-history.png',fullPage:true});
 await request(admin,'POST',path+'/access',{mode:'restricted',baseAccessVersion:2});await page.reload();await page.locator('#message').filter({hasText:'尚未获得'}).waitFor();assert.equal(await page.locator('#match').textContent(),'');
 const invitation=secret();await request(admin,'POST',path+'/viewer-invitations',{token:invitation});
 const viewer=await browser.newContext({viewport:{width:440,height:956}}),vp=await viewer.newPage();vp.on('pageerror',e=>errors.push(e.message));
 await vp.goto(`${origin}/watch/#${game.viewCode}/${invitation}`);await vp.locator('#nickname').fill('验证家长');await vp.locator('#apply-viewer').click();await vp.locator('#gate').waitFor({state:'hidden'});assert.equal(await vp.locator('#match').textContent(),'');
 const pending=(await request(admin,'GET',path+'/viewers')).viewers[0];assert.equal(pending.status,'pending');
 await request(admin,'POST',path+'/viewers',{viewerID:pending.id,allow:true,baseAccessVersion:3});await vp.reload();await vp.locator('#match').waitFor({state:'visible'});
 await request(admin,'POST',path+'/viewers',{viewerID:pending.id,allow:false,baseAccessVersion:4});await vp.waitForFunction(()=>document.querySelector('#match').textContent==='',{timeout:20000});
 await request(admin,'POST',path+'/access',{mode:'closed',baseAccessVersion:5});assert.ok((await request(member,'GET',path)).payload);
 for(const route of ['join','pair']){const token=secret();await page.goto(`${origin}/${route}/#${token}`);assert.ok((await page.locator('#open-app').getAttribute('href')).includes(token));assert.equal(await page.locator('a[href*="apps.apple.com"]').count(),1);assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);await page.screenshot({path:`${out}/${route}.png`,fullPage:true});}
 assert.deepEqual(errors,[]);summary.checks.push('HTTPS WebKit public, restricted approval, revocation, closed archive and iOS invitation/pairing landing pages passed');
 summary.teamID=team;summary.gameIDs=games.map(g=>g.id);summary.measurements=measurements;summary.passed=true;completed=true;
 writeFileSync(out+'/acceptance.json',JSON.stringify(summary,null,2)+'\n');console.log(JSON.stringify({passed:true,games:games.length,concurrentReads:summary.concurrentReads}));
 // Keep only synthetic team until on-server size/backup measurements. Credential stays outside published evidence.
 const privatePath=process.env.BM_VALIDATION_RECEIPT;assert.ok(privatePath,'Private cleanup receipt path required');
 writeFileSync(privatePath,JSON.stringify({team,admin,member,games:games.map(g=>g.id)}),{mode:0o600,flag:'wx'});
} catch(error){writeFileSync(out+'/failed.json',JSON.stringify({...summary,error:error.message,measurements},null,2)+'\n');throw error;}
finally{
 if(browser)await browser.close();
 if(team&&!completed){try{const d=await request(admin,'GET',`/teams/${team}`);await request(admin,'POST',`/teams/${team}/dissolve`,{confirm:true,name:d.team.name,baseRevision:d.team.revision});}catch{}}
}
